import { useEffect, useMemo, useRef, useState } from 'react'
import { api, normalizeCatalogTool, readSession, saveSession } from './api.js'
import { demoCatalog } from './demoCatalog.js'
import TermsAndConditionsPage from './TermsAndConditionsPage.jsx'
import { prioritizeFeaturedTools, resolveToolVisual, resolveToolVisualClass } from './toolVisuals.js'

const tools = demoCatalog
const money = new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0})
const toDateInput=value=>{
  const date=new Date(value)
  const offset=date.getTimezoneOffset()*60000
  return new Date(date.getTime()-offset).toISOString().slice(0,10)
}
const nextDay=new Date()
nextDay.setDate(nextDay.getDate()+1)
const fourthDay=new Date()
fourthDay.setDate(fourthDay.getDate()+4)
const defaultStartDate = toDateInput(nextDay)
const defaultReturnDate = toDateInput(fourthDay)
const serviceLocations = ['Bucaramanga', 'Floridablanca', 'Girón', 'Piedecuesta']
const storedLocation = typeof window === 'undefined' ? null : window.localStorage.getItem('tool-rental-location')
const requestedLocation = typeof window === 'undefined' ? null : new URLSearchParams(window.location.search).get('municipio')
const defaultLocation = serviceLocations.includes(requestedLocation) ? requestedLocation : serviceLocations.includes(storedLocation) ? storedLocation : serviceLocations[0]

function Icon({name,size=20}) {
  const paths = {
    arrow:<><path d="M5 12h14"/><path d="m13 6 6 6-6 6"/></>, search:<><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>,
    user:<><circle cx="12" cy="8" r="4"/><path d="M4 21c.6-4 3.3-6 8-6s7.4 2 8 6"/></>, calendar:<><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/></>,
    pin:<><path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/></>, heart:<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21l7.7-7.5a5.5 5.5 0 0 0 1.1-8.9Z"/>,
    check:<path d="m5 12 4 4L19 6"/>, shield:<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/>, menu:<><path d="M4 7h16M4 12h16M4 17h16"/></>, close:<><path d="m6 6 12 12M18 6 6 18"/></>,
    card:<><rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20"/></>, paypal:<><path d="M9 19H5l3-14h6c4 0 6 2 5 5-.7 3.6-3 5-7 5H9.8L9 19Z"/><path d="m11 14-1 6h4l.6-3h2.2c2.8 0 4.6-1.2 5.2-4"/></>,
    grid:<><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/></>, box:<><path d="m3 7 9 5 9-5M3 7l9-5 9 5v10l-9 5-9-5Z"/><path d="M12 12v10"/></>,
    logout:<><path d="M10 17l5-5-5-5M15 12H3"/><path d="M14 3h7v18h-7"/></>, chevron:<path d="m9 18 6-6-6-6"/>,
  }
  return <svg className="icon" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg>
}
function navigate(path){window.history.pushState({},'',path);window.dispatchEvent(new PopStateEvent('popstate'));const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;window.scrollTo({top:0,behavior:reducedMotion?'auto':'smooth'})}
function Brand(){return <button className="brand" onClick={()=>navigate('/')} aria-label="Ir al inicio"><span className="brand-symbol"><i/><i/><i/></span><span>tool<em>rental</em></span></button>}
function ToolVisual({tool,compact=false,priority=false}){const [failedUrls,setFailedUrls]=useState([]);const imageUrl=[tool.imageUrl,resolveToolVisual(tool)].find(url=>url&&!failedUrls.includes(url));return <div className={`tool-visual tool-${tool.color} ${resolveToolVisualClass(tool)} ${compact?'compact':''}`}>{imageUrl?<img src={imageUrl} alt={tool.name} loading={priority?'eager':'lazy'} decoding="async" onError={()=>setFailedUrls(current=>[...current,imageUrl])}/>:<><div className="visual-grid"/><div className="tool-silhouette" aria-hidden="true"><span/><span/><span/></div></>}<b>{tool.category}</b><small>TR—{tool.id.slice(0,3).toUpperCase()}</small></div>}

function Header({session,onOpenAuth,path,location,onLocationChange}){
  const [open,setOpen]=useState(false); const go=(path)=>{setOpen(false);navigate(path)}
  const active=target=>path===target||path.startsWith(`${target}/`)
  const initials=(session?.displayName||session?.email||'Mi cuenta').split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase()
  return <header className="site-header"><div className="nav-shell"><Brand/><nav id="main-navigation" className={`nav-links ${open?'open':''}`}><button className={active('/catalogo')?'active':''} aria-current={active('/catalogo')?'page':undefined} onClick={()=>go('/catalogo')}>Catálogo</button><button className={active('/como-funciona')?'active':''} aria-current={active('/como-funciona')?'page':undefined} onClick={()=>go('/como-funciona')}>Cómo funciona</button><button className={active('/nosotros')?'active':''} aria-current={active('/nosotros')?'page':undefined} onClick={()=>go('/nosotros')}>Sobre nosotros</button>{session&&<button className={active('/cuenta')?'active':''} aria-current={active('/cuenta')?'page':undefined} onClick={()=>go('/cuenta')}>Mi cuenta</button>}</nav><div className="nav-actions"><label className="location-action" aria-label="Municipio de servicio"><Icon name="pin" size={17}/><select value={location} onChange={event=>onLocationChange(event.target.value)}>{serviceLocations.map(city=><option key={city}>{city}</option>)}</select></label>{session?<button className="avatar-button" onClick={()=>navigate('/cuenta')} aria-label="Abrir mi cuenta">{initials}</button>:<button className="login-action" onClick={onOpenAuth}><Icon name="user" size={18}/> Ingresar</button>}<button className="publish-action" onClick={()=>go('/publicar')}>Publica tu herramienta <Icon name="arrow" size={17}/></button><button className="menu-action" onClick={()=>setOpen(!open)} aria-label={open?'Cerrar menú':'Abrir menú'} aria-expanded={open} aria-controls="main-navigation"><Icon name={open?'close':'menu'}/></button></div></div></header>
}
function Footer(){return <footer className="site-footer"><div className="footer-lead"><Brand/><h2>Tu proyecto empieza con la herramienta correcta.</h2><button className="button button-lime" onClick={()=>navigate('/catalogo')}>Explorar catálogo <Icon name="arrow"/></button></div><div className="footer-links"><div><strong>Plataforma</strong><button onClick={()=>navigate('/catalogo')}>Catálogo</button><button onClick={()=>navigate('/como-funciona')}>Cómo funciona</button><button onClick={()=>navigate('/cuenta')}>Mi cuenta</button></div><div><strong>Compañía</strong><button onClick={()=>navigate('/nosotros')}>Sobre nosotros</button><button onClick={()=>navigate('/informacion/contacto')}>Contacto</button><button onClick={()=>navigate('/informacion/faq')}>Preguntas frecuentes</button></div><div><strong>Legal</strong><button onClick={()=>navigate('/terms-and-conditions')}>Términos y condiciones</button><button onClick={()=>navigate('/informacion/privacidad')}>Privacidad</button></div></div><div className="footer-bottom"><span>© 2026 Tool Rental · Proyecto académico</span><span>Hecho para construir en Colombia</span></div></footer>}

function SearchBar({location,onLocationChange}){const [term,setTerm]=useState('');return <form className="search-bar" onSubmit={event=>{event.preventDefault();const params=new URLSearchParams();if(term.trim())params.set('q',term.trim());params.set('municipio',location);navigate(`/catalogo?${params}`)}}><div><Icon name="search"/><label htmlFor="home-search">¿Qué necesitas?</label><input id="home-search" value={term} onChange={event=>setTerm(event.target.value)} placeholder="Ej. rotomartillo, mezcladora, cortadora..."/></div><i/><label className="search-location"><Icon name="pin"/><span><small>Ubicación</small><select value={location} onChange={event=>onLocationChange(event.target.value)}>{serviceLocations.map(city=><option key={city} value={city}>{city}, Santander</option>)}</select></span></label><button aria-label="Buscar"><span>Buscar</span><Icon name="arrow"/></button></form>}
function HeroArtwork({location}){
  const imageRef=useRef(null)
  const ringRef=useRef(null)
  const move=event=>{if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||event.pointerType==='touch')return;const bounds=event.currentTarget.getBoundingClientRect();const x=(event.clientX-bounds.left)/bounds.width-.5;const y=(event.clientY-bounds.top)/bounds.height-.5;if(imageRef.current)imageRef.current.style.transform=`translate3d(${x*18}px,${y*14}px,0) rotate(-1deg) scale(1.12,.96)`;if(ringRef.current)ringRef.current.style.transform=`translate3d(${x*-24}px,${y*-18}px,0) rotate(${x*5}deg)`}
  const reset=()=>{if(imageRef.current)imageRef.current.style.transform='translate3d(0,0,0) rotate(-1deg) scale(1.12,.96)';if(ringRef.current)ringRef.current.style.transform='translate3d(0,0,0) rotate(0deg)'}
  return <div className="hero-artwork" onPointerMove={move} onPointerLeave={reset} aria-hidden="true"><div className="hero-orbit" ref={ringRef}><span/><span/><span/></div><div className="hero-crosshair"/><img ref={imageRef} src="/assets/hero-rotary-hammer-1200.png" alt="" fetchPriority="high"/><div className="hero-spec hero-spec-top"><small>CLASE</small><strong>PRO / 01</strong></div><div className="hero-spec hero-spec-bottom"><small>DISPONIBLE EN</small><strong><i/> {location.toUpperCase()}</strong></div><span className="hero-side-copy">HERRAMIENTAS<br/>QUE HACEN<br/>PROYECTOS<br/>REALES</span><span className="hero-coordinate">7.1193° N · 73.1227° W</span></div>
}
function FeaturedToolCard({tool,index}){const openTool=()=>navigate(`/herramienta/${tool.id}`);return <article className="featured-tool-card" role="link" tabIndex="0" aria-label={`Ver ${tool.name}`} onClick={openTool} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openTool()}}}><div className="featured-tool-media"><ToolVisual tool={tool} compact priority={index<2}/>{index===0&&<span className="featured-tool-badge">Destacado</span>}</div><div className="featured-tool-body"><p>{tool.category}</p><h3>{tool.name}</h3><div className="featured-tool-meta"><span>{tool.location?.split(',')[0]||'Ubicación por coordinar'}</span><span>{tool.stock>0?`${tool.stock} ${tool.stock===1?'unidad':'unidades'}`:'Sin existencias'}</span></div><div className="featured-tool-price"><strong>{money.format(tool.price)}</strong><span>/ día</span></div><div className={`featured-tool-status ${tool.stock>0?'available':'unavailable'}`}><i/><span>{tool.stock>0?'Con unidades operativas':'Sin unidades operativas'}</span><Icon name="arrow" size={17}/></div></div></article>}
function FeaturedSection({catalogTools,dataMode}){const pageSize=5;const [startIndex,setStartIndex]=useState(0);const orderedTools=useMemo(()=>prioritizeFeaturedTools(catalogTools),[catalogTools]);const lastPageStart=Math.max(0,Math.floor((orderedTools.length-1)/pageSize)*pageSize);const visibleStart=Math.min(startIndex,lastPageStart);const visibleTools=orderedTools.slice(visibleStart,visibleStart+pageSize);return <section id="destacados" className="featured-section" data-reveal><div className="page-shell featured-shell"><div className="featured-heading"><div><p className="kicker dark"><span/> Equipos disponibles ahora</p><h2>Equipos destacados</h2><p>{dataMode==='api'?'Selección construida con publicaciones recibidas del catálogo público.':'Muestra demostrativa para revisar el diseño antes de conectar publicaciones reales.'}</p></div><div className="featured-actions"><button className="text-link" onClick={()=>navigate('/catalogo')}>Ver todos los equipos <Icon name="arrow"/></button><button className="featured-arrow" aria-label="Ver equipos anteriores" disabled={visibleStart===0} onClick={()=>setStartIndex(Math.max(0,visibleStart-pageSize))}>←</button><button className="featured-arrow" aria-label="Ver equipos siguientes" disabled={visibleStart>=lastPageStart} onClick={()=>setStartIndex(Math.min(lastPageStart,visibleStart+pageSize))}>→</button></div></div>{dataMode==='demo'&&<p className="featured-disclosure">Contenido demostrativo: precios, ubicaciones y unidades son provisionales.</p>}<div className="featured-grid" aria-live="polite">{visibleTools.map((tool,index)=><FeaturedToolCard key={tool.id} tool={tool} index={index}/>)}</div></div></section>}
function HomePage({catalogTools,dataMode,location,onLocationChange}){return <>
  <section className="home-hero"><div className="hero-noise"/><div className="hero-content page-shell"><div className="hero-copy"><p className="kicker"><span/> Equipos profesionales, sin comprarlos</p><h1><span className="hero-line"><b>Haz</b> más.</span><span className="hero-line hero-line-accent">Compra <em>menos.</em></span></h1><p className="hero-subtitle">Encuentra herramientas cerca de tu proyecto, consulta fechas y crea una solicitud trazable.</p><div className="hero-actions"><button className="button button-lime" onClick={()=>navigate('/catalogo')}>Explorar equipos <Icon name="arrow"/></button><button className="hero-secondary" onClick={()=>navigate('/como-funciona')}>Cómo funciona <span>↗</span></button></div><div className="trust-row"><span><Icon name="calendar" size={20}/><b>Fechas inclusivas<small>Cálculo consistente</small></b></span><span><Icon name="shield" size={20}/><b>Sesiones protegidas<small>Renovación segura</small></b></span><span><Icon name="box" size={20}/><b>Inventario consultable<small>Datos del catálogo</small></b></span><span><Icon name="check" size={20}/><b>Estados trazables<small>Seguimiento real</small></b></span></div></div><HeroArtwork location={location}/><div className="hero-search"><SearchBar location={location} onLocationChange={onLocationChange}/></div></div><div className="scroll-note"><span/> DESLIZA PARA EXPLORAR</div></section>
  <div className="industrial-marquee" aria-hidden="true"><div>PERFORA <i/> CONSTRUYE <i/> LIMPIA <i/> ELEVA <i/> REPARA <i/> PERFORA <i/> CONSTRUYE <i/> LIMPIA <i/> ELEVA <i/> REPARA <i/></div></div>
  <section className="category-section page-shell" data-reveal><div className="section-title-row"><div><p className="kicker dark"><span/> Encuentra lo que buscas</p><h2>Herramientas para<br/><em>cada proyecto.</em></h2></div><button className="text-link" onClick={()=>navigate('/catalogo')}>Ver todo el catálogo <Icon name="arrow"/></button></div><div className="category-tiles">{[['Demolición','Rompedores, demoledores y más.'],['Concreto','Mezcladoras, vibradores y equipos.'],['Corte','Cortadoras, sierras y discos.'],['Limpieza','Aspiradoras e hidrolavadoras.'],['Energía','Generadores y plantas.']].map(([category,description],index)=>{const count=catalogTools.filter(tool=>tool.category===category).length;return <button key={category} onClick={()=>navigate(`/catalogo?categoria=${encodeURIComponent(category)}&municipio=${encodeURIComponent(location)}`)} aria-label={`${category}: ${dataMode==='api'?`${count} equipos disponibles`:'explorar muestra'}`}><span className={`category-icon category-${index+1}`}><i/><b/></span><span className="category-index">0{index+1}</span><strong>{category}</strong><small>{description}</small><Icon name="arrow"/></button>})}</div></section>
  <FeaturedSection catalogTools={catalogTools} dataMode={dataMode}/>
  <section className="steps-section page-shell" data-reveal><div className="steps-intro"><p className="kicker dark"><span/> Así de simple</p><h2>Cómo funciona.</h2><p>El flujo vigente conserva confirmación del proveedor y pago académico claramente identificado.</p></div><div className="steps-list">{[['01','Busca','Explora el catálogo y consulta las fechas.'],['02','Solicita','Elige recogida o entrega y crea la solicitud.'],['03','Confirma','El proveedor vuelve a validar la unidad.'],['04','Haz más','Sigue entrega, uso y devolución desde tu cuenta.']].map(x=><article key={x[0]}><span>{x[0]}</span><div><h3>{x[1]}</h3><p>{x[2]}</p></div><Icon name="arrow"/></article>)}</div></section>
  <section className="supplier-cta" data-reveal><div className="page-shell"><p className="kicker"><span/> Para proveedores</p><h2>Tu equipo puede<br/><em>seguir produciendo.</em></h2><p>Conoce el proceso para operar como proveedor y administrar únicamente tus propios recursos.</p><button className="button button-light" onClick={()=>navigate('/publicar')}>Publica tu herramienta <Icon name="arrow"/></button></div><div className="cta-orbit" aria-hidden="true"><span>PUBLICA</span><b>ACTIVA</b><small>ADMINISTRA</small></div></section>
  </>}
function ToolCard({tool}){const openTool=()=>navigate(`/herramienta/${tool.id}`);const tilt=event=>{if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||event.pointerType==='touch')return;const bounds=event.currentTarget.getBoundingClientRect();const x=(event.clientX-bounds.left)/bounds.width-.5;const y=(event.clientY-bounds.top)/bounds.height-.5;event.currentTarget.style.transform=`perspective(900px) rotateX(${y*-3}deg) rotateY(${x*4}deg) translateY(-6px)`};const reset=event=>{event.currentTarget.style.transform=''};return <article className="tool-card" role="link" tabIndex="0" aria-label={`Ver ${tool.name}`} onPointerMove={tilt} onPointerLeave={reset} onClick={openTool} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openTool()}}}><div className="tool-card-media"><ToolVisual tool={tool} compact/><span className="tool-tag">{tool.accent}</span><span className="card-corner" aria-hidden="true"/></div><div className="tool-card-body"><p>{tool.category}</p><h3>{tool.name}</h3><div className="tool-meta"><span><Icon name="pin" size={15}/>{tool.location?.split(',')[0]||'Ubicación por coordinar'}</span>{tool.rating&&tool.reviews?<span>★ {tool.rating} <small>({tool.reviews})</small></span>:<span>{tool.stock>0?`${tool.stock} ${tool.stock===1?'unidad':'unidades'}`:'Sin existencias'}</span>}</div><div className="tool-price"><strong>{money.format(tool.price)}</strong><span>/ día</span><Icon name="arrow"/></div></div></article>}

function CatalogPage({catalogTools,dataMode,location,onLocationChange}){const params=new URLSearchParams(window.location.search);const [query,setQuery]=useState(params.get('q')||'');const [category,setCategory]=useState(params.get('categoria')||'Todas');const [sort,setSort]=useState('Recomendados');const availableCategories=['Todas',...new Set(catalogTools.map(tool=>tool.category))];useEffect(()=>{const next=new URLSearchParams();if(query.trim())next.set('q',query.trim());if(category!=='Todas')next.set('categoria',category);next.set('municipio',location);window.history.replaceState({},'',`/catalogo?${next}`)},[query,category,location]);const visible=useMemo(()=>catalogTools.filter(tool=>(category==='Todas'||tool.category===category)&&`${tool.name} ${tool.category}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='Menor precio'?a.price-b.price:sort==='Mayor precio'?b.price-a.price:0),[catalogTools,query,category,sort]);return <main className="catalog-page page-shell page-top"><div className="catalog-heading" data-reveal><div><p className="breadcrumb"><button onClick={()=>navigate('/')}>Inicio</button> / <strong>Catálogo</strong></p><span className="catalog-overline">EQUIPOS · {location.toUpperCase()} · SANTANDER</span><h1>Encuentra tu próxima <em>herramienta.</em></h1><p>{visible.length} {visible.length===1?'equipo':'equipos'} {dataMode==='api'?'publicados':'en la muestra demostrativa'}.</p></div><div className="catalog-stat"><small>CATEGORÍAS</small><strong>{availableCategories.length-1}</strong><span>formas de poner<br/>tu proyecto en marcha</span></div></div>{dataMode==='demo'?<div className="data-notice" role="status">Vista demostrativa etiquetada: precios, unidades y ubicaciones desaparecen al conectar el catálogo real.</div>:<div className="data-notice neutral" role="status">La selección de municipio define tu zona de búsqueda; la API pública todavía no expone un campo territorial por publicación.</div>}<div className="catalog-controls" data-reveal><div className="catalog-search"><Icon name="search"/><input aria-label="Buscar herramienta o categoría" value={query} onChange={event=>setQuery(event.target.value)} placeholder="Buscar herramienta o categoría"/><button type="button" onClick={()=>setQuery(query.trim())}>Buscar <Icon name="arrow" size={17}/></button></div><label className="catalog-location"><span>Municipio</span><select value={location} onChange={event=>onLocationChange(event.target.value)}>{serviceLocations.map(city=><option key={city}>{city}</option>)}</select></label><div className="category-pills">{availableCategories.map(item=><button key={item} className={category===item?'active':''} onClick={()=>setCategory(item)}>{item}</button>)}</div></div><div className="catalog-toolbar"><span><i/> {visible.length} resultados</span><label>Ordenar por <select value={sort} onChange={event=>setSort(event.target.value)}><option>Recomendados</option><option>Menor precio</option><option>Mayor precio</option></select></label></div>{visible.length?<div className="tool-grid catalog-grid">{visible.map(tool=><ToolCard key={tool.id} tool={tool}/>)}</div>:<EmptyState title="No encontramos coincidencias" text="Prueba otra palabra o elimina los filtros." action={()=>{setQuery('');setCategory('Todas')}}/>}</main>}
function DateField({label,value,onChange,min}){return <label className="date-field"><span>{label}</span><div><Icon name="calendar" size={18}/><input type="date" value={value} min={min} onChange={e=>onChange(e.target.value)}/></div></label>}
function getDays(start,end){if(!start||!end)return 1;return Math.max(1,Math.round((new Date(`${end}T12:00:00`)-new Date(`${start}T12:00:00`))/86400000)+1)}
function ToolDetailPage({id,onReserve,catalogTools,dataMode}){const tool=catalogTools.find(item=>item.id===id)||catalogTools[0]||tools[0];const [startDate,setStartDate]=useState(defaultStartDate);const [returnDate,setReturnDate]=useState(defaultReturnDate);const days=getDays(startDate,returnDate);const hasStock=tool.stock>0;return <main className="detail-page page-shell page-top"><nav className="detail-breadcrumb" aria-label="Ruta de navegación"><button onClick={()=>navigate('/')}>Inicio</button><span>/</span><button onClick={()=>navigate('/catalogo')}>Catálogo</button><span>/</span><button onClick={()=>navigate(`/catalogo?categoria=${encodeURIComponent(tool.category)}`)}>{tool.category}</button><span>/</span><strong>{tool.name}</strong></nav>{dataMode==='demo'&&<div className="data-notice" role="status">Ficha demostrativa: esta herramienta, su precio, ubicación y unidades no son una publicación real.</div>}<div className="detail-layout"><section className="detail-gallery" aria-label="Galería de herramienta"><div className="thumbnail-rail"><button className="active" aria-label="Ver imagen principal"><ToolVisual tool={tool} compact/></button><button disabled title="No hay más imágenes publicadas">+0</button></div><div className="detail-main-visual"><ToolVisual tool={tool} priority/>{!tool.imageUrl&&<span className="placeholder-note">Representación visual · sin fotografía del proveedor</span>}</div></section><section className="detail-info"><p className="detail-overline">{tool.category} <span/> {hasStock?'Con unidades registradas':'Sin existencias'}</p><h1>{tool.name}</h1><p className="detail-description-copy">{tool.description}</p><div className="detail-specs"><span><Icon name="box"/><strong>{tool.stock}</strong><small>unidades operativas</small></span><span><Icon name="pin"/><strong>{tool.location?.split(',')[0]||'Por coordinar'}</strong><small>ubicación publicada</small></span><span><Icon name="calendar"/><strong>Inclusivos</strong><small>días facturables</small></span></div><div className="detail-integrity"><Icon name="shield"/><div><strong>Información disponible en el catálogo</strong><p>No mostramos reseñas, certificaciones ni verificación del proveedor porque la API pública actual no las acredita.</p></div></div></section><aside className="booking-card"><div className="booking-price"><strong>{money.format(tool.price)}</strong><span>/ día</span></div><div className={`availability-badge ${hasStock?'':'unavailable'}`}><span/><strong>{hasStock?`${tool.stock} ${tool.stock===1?'unidad operativa':'unidades operativas'}`:'Sin unidades operativas'}</strong></div><DateField label="Fecha de inicio" value={startDate} min={defaultStartDate} onChange={value=>{setStartDate(value);if(value>returnDate)setReturnDate(value)}}/><DateField label="Fecha de devolución" value={returnDate} min={startDate} onChange={setReturnDate}/><div className="booking-summary"><span>{money.format(tool.price)} × {days} {days===1?'día':'días'}</span><strong>{money.format(tool.price*days)}</strong><span>Entrega e impuestos</span><strong>Por calcular</strong></div><div className="booking-total"><span>Subtotal estimado</span><strong>{money.format(tool.price*days)}</strong></div><button className="button button-lime wide" disabled={!hasStock} onClick={()=>onReserve({tool,startDate,returnDate,days})}>{hasStock?'Comprobar disponibilidad':'No disponible'} <Icon name="arrow"/></button><small className="booking-note">La disponibilidad y el total se validan nuevamente en el backend. No se realizará ningún cobro.</small></aside></div><section className="fulfillment-preview"><article><Icon name="pin"/><div><strong>Recogida con el proveedor</strong><p>El punto se coordina después de que la solicitud sea confirmada.</p></div></article><article><Icon name="box"/><div><strong>Entrega del proveedor</strong><p>Si está disponible, la tarifa versionada se calcula antes de crear la solicitud.</p></div></article><div className="detail-benefits"><span><Icon name="calendar"/>Fechas trazables</span><span><Icon name="shield"/>Sesión protegida</span></div></section><section className="detail-technical"><p className="kicker"><span/> Lo que sí sabemos</p><h2>Información para decidir,<br/><em>sin inventar atributos.</em></h2><div><span><strong>{tool.category}</strong><small>Categoría</small></span><span><strong>{money.format(tool.price)}</strong><small>Tarifa diaria publicada</small></span><span><strong>{tool.stock}</strong><small>Unidades operativas</small></span></div></section></main>}

function QuotePage({reservation,session,onContinue}){
  const [fulfillmentMethod,setFulfillmentMethod]=useState('CUSTOMER_PICKUP')
  const [scheduledFulfillmentAt,setScheduledFulfillmentAt]=useState('')
  const [deliveryAddressLine,setDeliveryAddressLine]=useState('')
  const [deliveryCity,setDeliveryCity]=useState('Bucaramanga')
  const [deliveryRegion,setDeliveryRegion]=useState('Santander')

  if(!reservation)return <EmptyState title="Tu cotización está vacía" text="Selecciona primero una herramienta y las fechas de uso." action={()=>navigate('/catalogo')} actionText="Explorar catálogo"/>

  const subtotal=reservation.tool.price*reservation.days
  const deliveryRequired=fulfillmentMethod==='SUPPLIER_DELIVERY'
  const logisticsReady=scheduledFulfillmentAt&&(!deliveryRequired||(deliveryAddressLine&&deliveryCity&&deliveryRegion))
  const continueCheckout=()=>onContinue({
    fulfillmentMethod,
    scheduledFulfillmentAt,
    deliveryAddressLine:deliveryRequired?deliveryAddressLine:null,
    deliveryCity:deliveryRequired?deliveryCity:null,
    deliveryRegion:deliveryRequired?deliveryRegion:null,
    deliveryCountryCode:deliveryRequired?'CO':null,
  })

  return <main className="checkout-page page-shell page-top"><div className="checkout-steps"><span className="done">1</span><i/><span className="active">2</span><i/><span>3</span><small>Herramienta</small><small>Solicitud</small><small>Confirmación</small></div><div className="checkout-layout"><section><p className="kicker dark"><span/> Revisa antes de continuar</p><h1>Tu cotización.</h1><div className="quote-tool"><ToolVisual tool={reservation.tool} compact/><div><small>{reservation.tool.category}</small><h3>{reservation.tool.name}</h3><p><Icon name="calendar" size={17}/>{reservation.startDate} → {reservation.returnDate}</p><p><Icon name="pin" size={17}/>{reservation.tool.location}</p></div></div><div className="logistics-card"><h2>Entrega o recogida</h2><p>Define cómo y cuándo esperas recibir el equipo. El proveedor debe confirmar la solicitud.</p><div className="fulfillment-options"><button className={fulfillmentMethod==='CUSTOMER_PICKUP'?'active':''} onClick={()=>setFulfillmentMethod('CUSTOMER_PICKUP')}><Icon name="pin"/><span><strong>Recoger con el proveedor</strong><small>Coordina el punto después de la confirmación.</small></span></button><button className={deliveryRequired?'active':''} onClick={()=>setFulfillmentMethod('SUPPLIER_DELIVERY')}><Icon name="box"/><span><strong>Entrega del proveedor</strong><small>La tarifa versionada se calcula en el backend.</small></span></button></div><label className="form-field"><span>Fecha y hora programada</span><input type="datetime-local" min={`${reservation.startDate}T00:00`} value={scheduledFulfillmentAt} onChange={event=>setScheduledFulfillmentAt(event.target.value)} required/></label>{deliveryRequired&&<div className="delivery-fields"><label className="form-field"><span>Dirección de entrega</span><input value={deliveryAddressLine} onChange={event=>setDeliveryAddressLine(event.target.value)} placeholder="Calle, número y complemento" required/></label><div className="two-fields"><label className="form-field"><span>Ciudad</span><input value={deliveryCity} onChange={event=>setDeliveryCity(event.target.value)} required/></label><label className="form-field"><span>Departamento o región</span><input value={deliveryRegion} onChange={event=>setDeliveryRegion(event.target.value)} required/></label></div></div>}</div><div className="notice-card"><Icon name="shield"/><div><strong>Precio base, sin cálculo tributario definitivo</strong><p>La plataforma todavía no aplica impuestos ni protección. La entrega se cotiza con la configuración versionada del backend.</p></div></div>{reservation.apiError&&<div className="form-error" role="alert">{reservation.apiError}</div>}{!session&&<div className="auth-nudge"><h3>Ingresa para crear la solicitud</h3><p>Conservaremos esta cotización mientras completas el acceso.</p></div>}</section><aside className="price-card"><h2>Resumen</h2><div><span>Tarifa diaria</span><strong>{money.format(reservation.tool.price)}</strong><span>Días facturables</span><strong>{reservation.days}</strong><span>Subtotal alquiler</span><strong>{money.format(subtotal)}</strong></div><div className="split-payment"><small>Pago simulado, después de confirmar</small><p><span>Primera mitad · 50%</span><strong>{money.format(subtotal/2)}</strong></p><p><span>Al finalizar · 50%</span><strong>{money.format(subtotal/2)}</strong></p></div><div className="price-total"><span>Total base estimado</span><strong>{money.format(subtotal)}</strong></div><button className="button button-dark wide" disabled={Boolean(session)&&!logisticsReady} onClick={continueCheckout}>{session?'Crear solicitud':'Ingresar y continuar'} <Icon name="arrow"/></button><button className="button button-ghost wide" onClick={()=>navigate(`/herramienta/${reservation.tool.id}`)}>Editar fechas</button><p className="checkout-legal">Al continuar podrás revisar los <button onClick={()=>navigate('/terms-and-conditions')}>Términos y Condiciones</button>. No se realizará ningún cobro en esta etapa.</p></aside></div></main>}

function PaymentPage({reservation,onPaid}){const [method,setMethod]=useState('CREDIT_CARD');const [network,setNetwork]=useState('VISA');const [lastFour,setLastFour]=useState('');const [expiry,setExpiry]=useState('');const amount=reservation?reservation.tool.price*reservation.days/2:0;const approve=()=>{const [year,month]=expiry.split('-');onPaid({paymentMethod:method,cardNetwork:method==='PAYPAL'?null:network,cardLastFour:method==='PAYPAL'?null:lastFour,cardExpiryMonth:month?Number(month):null,cardExpiryYear:year?Number(year):null})};return <main className="payment-page page-shell page-top"><div className="payment-heading"><h1>Pago simulado.</h1><p>Confirma la primera mitad para completar la solicitud.</p></div><div className="simulation-banner"><span>DEMO</span><div><strong>Esta operación es una simulación académica</strong><p>No se realiza un cobro real ni se conecta con una pasarela de pagos.</p></div></div>{reservation?.apiError&&<div className="form-error" role="alert">{reservation.apiError}</div>}<div className="payment-layout"><section className="payment-form"><h2>Elige cómo simular el pago</h2><div className="payment-methods"><button className={method!=='PAYPAL'?'active':''} onClick={()=>setMethod('CREDIT_CARD')}><Icon name="card"/><span><strong>Tarjeta</strong><small>Crédito o débito</small></span></button><button className={method==='PAYPAL'?'active':''} onClick={()=>setMethod('PAYPAL')}><Icon name="paypal"/><span><strong>PayPal</strong><small>Cuenta simulada</small></span></button></div>{method!=='PAYPAL'?<><div className="network-choice"><button className={network==='VISA'?'active':''} onClick={()=>setNetwork('VISA')}><b>VISA</b></button><button className={network==='MASTERCARD'?'active':''} onClick={()=>setNetwork('MASTERCARD')}><i/><i/><b>mastercard</b></button></div><div className="safe-fields"><label><span>Últimos 4 dígitos</span><input value={lastFour} onChange={e=>setLastFour(e.target.value.replace(/\D/g,'').slice(0,4))} inputMode="numeric" placeholder="1234"/></label><label><span>Vencimiento</span><input value={expiry} onChange={e=>setExpiry(e.target.value)} type="month"/></label></div><div className="privacy-callout"><Icon name="shield"/><p><strong>Nunca solicitamos el número completo ni el CVV.</strong><br/>Solo se envían al backend la red, vencimiento y últimos cuatro dígitos.</p></div></>:<div className="paypal-demo"><Icon name="paypal" size={36}/><div><strong>Cuenta PayPal de demostración</strong><p>No necesitas credenciales. La aprobación se simula dentro del proyecto.</p></div></div>}</section><aside className="payment-summary"><span>Primera mitad · 50%</span><strong>{money.format(amount)}</strong><p>{reservation?.tool.name||'Herramienta seleccionada'}</p><dl><div><dt>Periodo</dt><dd>{reservation?.days||1} días</dd></div><div><dt>Método</dt><dd>{method==='PAYPAL'?'PayPal':`${network} simulada`}</dd></div></dl><button className="button button-lime wide" disabled={method!=='PAYPAL'&&(lastFour.length!==4||!expiry)} onClick={approve}>Simular aprobación <Icon name="arrow"/></button><small>Consulta los <button className="inline-link" onClick={()=>navigate('/terms-and-conditions')}>Términos y Condiciones</button> antes de continuar.</small></aside></div></main>}
function SuccessPage({reservation}){const reservationCode=reservation?.reservationId?`TR-${String(reservation.reservationId).slice(0,8).toUpperCase()}`:'TR-DEMO';return <main className="success-page page-shell page-top"><div className="success-mark"><Icon name="check" size={42}/></div><p className="kicker dark"><span/> Solicitud creada</p><h1>Tu herramienta está<br/>un paso más cerca.</h1><p>El proveedor debe confirmar la disponibilidad. No se realizó ningún cobro; el primer pago simulado solo estará disponible después de la confirmación.</p><div className="success-ticket"><div><small>Código</small><strong>{reservationCode}</strong></div><div><small>Equipo</small><strong>{reservation?.tool.name||tools[0].name}</strong></div><div><small>Estado</small><strong>Pendiente de confirmación</strong></div></div><p className="success-legal">Consulta los <button onClick={()=>navigate('/terms-and-conditions')}>Términos y Condiciones</button> aplicables a esta simulación académica.</p><div className="success-actions"><button className="button button-dark" onClick={()=>navigate('/cuenta')}>Ver mis reservas <Icon name="arrow"/></button><button className="button button-ghost" onClick={()=>navigate('/catalogo')}>Seguir explorando</button></div></main>}

function AuthModal({onClose,onLogin}){
  const [mode,setMode]=useState('login'),[sent,setSent]=useState(false),[error,setError]=useState(''),[busy,setBusy]=useState(false)
  const authenticate=async data=>{setBusy(true);setError('');try{const result=mode==='register'?await api.register(data):await api.login(data.email,data.password);onLogin(result)}catch(reason){setError(reason.message)}finally{setBusy(false)}}
  const recover=async event=>{event.preventDefault();setBusy(true);setError('');try{const result=await api.recoverPassword(new FormData(event.currentTarget).get('email'));setSent(result||{accepted:true})}catch(reason){setError(reason.message)}finally{setBusy(false)}}
  return <div className="modal-backdrop" onMouseDown={event=>event.target===event.currentTarget&&onClose()}><section className="auth-modal" role="dialog" aria-modal="true" aria-live="polite"><button className="modal-close" onClick={onClose} aria-label="Cerrar acceso"><Icon name="close"/></button><Brand/>{error&&<div className="form-error" role="alert">{error}</div>}{mode==='login'&&<><h2>Ingresa a tu cuenta.</h2><AuthFields submitText="Ingresar" onSubmit={authenticate} busy={busy}/><p className="form-switch"><button onClick={()=>setMode('recovery')}>¿Olvidaste tu contraseña?</button></p><div className="modal-separator"><span>o</span></div><p className="form-switch">¿Aún no tienes cuenta? <button onClick={()=>setMode('register')}>Regístrate</button></p></>}{mode==='register'&&<><h2>Crea tu cuenta de cliente.</h2><div className="registration-scope"><Icon name="user"/><p>El endpoint público actual asigna exclusivamente el rol <strong>Customer</strong>. Para publicar herramientas consulta el proceso de proveedor.</p></div><AuthFields register submitText="Crear cuenta" onSubmit={authenticate} busy={busy}/><p className="legal-copy">Antes de crear tu cuenta, consulta los <button onClick={()=>{onClose();navigate('/terms-and-conditions')}}>Términos y Condiciones</button>. La aceptación y el mercadeo opcional deben solicitarse por separado.</p><p className="form-switch"><button onClick={()=>{onClose();navigate('/publicar')}}>Quiero ser proveedor</button></p><p className="form-switch">¿Ya tienes cuenta? <button onClick={()=>setMode('login')}>Ingresa</button></p></>}{mode==='recovery'&&<><h2>Restablece tu contraseña.</h2>{sent?<div className="recovery-success"><Icon name="check"/><strong>Solicitud aceptada</strong><p>Si la cuenta existe, recibirás las instrucciones por el canal configurado.</p><button className="button button-dark wide" onClick={()=>setMode('login')}>Volver al ingreso</button></div>:<form onSubmit={recover}><label className="form-field"><span>Correo electrónico</span><input name="email" type="email" required placeholder="tu@correo.com"/></label><button className="button button-dark wide" disabled={busy}>{busy?'Conectando…':'Solicitar recuperación'} <Icon name="arrow"/></button></form>}<p className="form-switch"><button onClick={()=>setMode('login')}>← Volver</button></p></>}</section></div>
}
function AuthFields({register=false,submitText,onSubmit,busy}){const submit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));onSubmit(register?{email:data.email,displayName:data.displayName,password:data.password,personType:'NATURAL_PERSON',documentType:data.documentType,documentNumber:data.documentNumber,billingName:data.displayName}:data)};return <form onSubmit={submit}>{register&&<><label className="form-field"><span>Nombre completo</span><input name="displayName" required placeholder="Andrea Moreno"/></label><div className="two-fields"><label className="form-field"><span>Tipo de documento</span><select name="documentType" defaultValue="CC"><option>CC</option><option>CE</option><option>PASSPORT</option></select></label><label className="form-field"><span>Número</span><input name="documentNumber" required/></label></div></>}<label className="form-field"><span>Correo electrónico</span><input name="email" type="email" required placeholder="tu@correo.com"/></label><label className="form-field"><span>Contraseña</span><input name="password" type="password" required minLength="12"/><small>Mínimo 12 caracteres</small></label><button className="button button-dark wide" disabled={busy}>{busy?'Conectando…':submitText} <Icon name="arrow"/></button></form>}

function Metric({label,value,trend}){return <article className="metric-card"><span>{label}</span><strong>{value}</strong><p>{trend}</p></article>}
function reservationValue(reservation,key){const value=reservation?.[key];return value?.value??value??null}
function AccountPage({session,onLogout}){const [reservations,setReservations]=useState([]);const [state,setState]=useState(()=>session?'loading':'idle');const [error,setError]=useState('');const [activeSection,setActiveSection]=useState('reservations');useEffect(()=>{let active=true;if(!session)return()=>{active=false};api.listReservations().then(items=>{if(active){setReservations(Array.isArray(items)?items:[]);setState('ready')}}).catch(reason=>{if(active){setError(reason.message);setState('error')}});return()=>{active=false}},[session]);if(!session)return <EmptyState title="Ingresa para ver tu cuenta" text="Consulta aquí tus reservas y el estado real de tu operación." action={()=>window.dispatchEvent(new Event('open-auth'))} actionText="Ingresar"/>;const name=session.displayName||session.email;const pending=reservations.filter(item=>String(item.status).includes('PENDING')).length;const modules=[['reservations','calendar','Mis reservas','Consulta solicitudes y estados persistidos.'],['rentals','box','Alquileres','Se habilitarán al integrar el endpoint de alquileres.'],['invoices','card','Comprobantes','Documentos académicos, cuando existan.'],['security','shield','Perfil y seguridad','Sesión y credenciales de tu cuenta.']];return <main className="account-page"><section className="account-hero"><div className="page-shell"><div><p className="kicker"><span/> Mi perfil</p><h1>Tu perfil, tus alquileres,<br/><em>todo en un solo lugar.</em></h1><p>Consulta tus solicitudes con datos de tu sesión y del backend.</p><button className="button button-lime" onClick={()=>navigate('/catalogo')}>Explorar herramientas <Icon name="arrow"/></button></div><img src="/assets/hero-rotary-hammer-1200.png" alt=""/></div></section><div className="account-layout page-shell"><aside className="profile-card"><span className="profile-avatar">{name.slice(0,1).toUpperCase()}</span><h2>{name}</h2><p>{session.email}</p><span className="role-badge">{session.roles?.join(' · ')||'Cuenta autenticada'}</span><div><button onClick={()=>setActiveSection('security')}><Icon name="user"/>Mis datos <Icon name="chevron"/></button><button onClick={onLogout}><Icon name="logout"/>Cerrar sesión <Icon name="chevron"/></button></div></aside><section className="account-workspace"><div className="account-modules">{modules.map(([id,icon,title,copy])=><button key={id} className={activeSection===id?'active':''} onClick={()=>setActiveSection(id)}><span><Icon name={icon}/></span><div><strong>{title}</strong><p>{copy}</p></div><Icon name="arrow"/></button>)}</div><div className="account-panel" aria-live="polite">{activeSection==='reservations'?<><div className="panel-heading"><div><p className="kicker dark"><span/> Actividad real</p><h2>Mis reservas</h2></div><span className="status-pill amber">{pending} pendientes</span></div>{state==='loading'&&<p className="panel-state">Cargando tus reservas…</p>}{state==='error'&&<div className="form-error" role="alert">{error}</div>}{state==='ready'&&!reservations.length&&<div className="account-empty"><Icon name="calendar" size={34}/><h3>Aún no tienes reservas</h3><p>Cuando crees una solicitud desde el catálogo, aparecerá aquí.</p><button className="button button-dark" onClick={()=>navigate('/catalogo')}>Explorar catálogo</button></div>}{reservations.map(item=><article className="reservation-row" key={String(reservationValue(item,'id'))}><div><span className="status-pill amber">{String(item.status).replaceAll('_',' ')}</span><h3>Reserva {String(reservationValue(item,'id')).slice(0,8).toUpperCase()}</h3><p>{item.period?.startDate} → {item.effectiveReturnDate||item.period?.returnDate}</p></div><div><small>Total registrado</small><strong>{money.format(Number(item.total?.amount??0))}</strong></div></article>)}</>:activeSection==='security'?<div className="account-empty"><Icon name="shield" size={34}/><h3>Sesión protegida</h3><p>El access token vive solo en memoria y la renovación usa una cookie HttpOnly. La edición de perfil todavía no tiene un contrato público dedicado.</p></div>:<div className="account-empty"><Icon name={activeSection==='rentals'?'box':'card'} size={34}/><h3>Integración pendiente</h3><p>Esta sección no mostrará cifras ni documentos ficticios. Se activará cuando su endpoint orientado al cliente esté integrado.</p></div>}</div></section></div><section className="account-cta page-shell"><div><p className="kicker"><span/> Sigue explorando</p><h2>¿Tienes un nuevo proyecto en mente?</h2><p>Encuentra la herramienta adecuada para el siguiente trabajo.</p><button className="button button-lime" onClick={()=>navigate('/catalogo')}>Explorar herramientas <Icon name="arrow"/></button></div></section></main>}
function entityId(value){return value?.value??value}
function BusinessDashboard({role,session}){const provider=role==='provider';const requiredRole=provider?'SUPPLIER':'ADMIN';const authorized=Boolean(session?.roles?.includes(requiredRole));const [data,setData]=useState({tools:[],units:[],categories:[],users:[]});const [state,setState]=useState('loading');const [error,setError]=useState('');const [activeForm,setActiveForm]=useState('tool');useEffect(()=>{let active=true;if(!authorized)return()=>{active=false};const requests=provider?Promise.all([api.listTools(),api.listEquipmentUnits(),api.listCategories()]):Promise.all([api.listTools(),api.listEquipmentUnits(),api.listCategories(),api.listUsers()]);requests.then(([allTools,units,categories,users=[]])=>{if(!active)return;const visibleTools=provider?allTools.filter(tool=>String(entityId(tool.supplierId))===String(session.userId)):allTools;setData({tools:visibleTools,units,categories,users});setState('ready')}).catch(reason=>{if(active){setError(reason.message);setState('error')}});return()=>{active=false}},[authorized,provider,session?.userId]);const createTool=async event=>{event.preventDefault();setError('');const form=new FormData(event.currentTarget);try{const created=await api.createTool({categoryId:form.get('categoryId'),name:form.get('name'),description:form.get('description'),dailyRate:Number(form.get('dailyRate')),currency:'COP',imageUrls:[],published:form.get('published')==='on'});setData(current=>({...current,tools:[created,...current.tools]}));event.currentTarget.reset()}catch(reason){setError(reason.message)}};const createUnit=async event=>{event.preventDefault();setError('');const form=new FormData(event.currentTarget);try{const created=await api.createEquipmentUnit({toolId:form.get('toolId'),inventoryCode:form.get('inventoryCode'),serialNumber:form.get('serialNumber')||null,currentCondition:form.get('currentCondition'),status:'OPERATIONAL'});setData(current=>({...current,units:[created,...current.units]}));event.currentTarget.reset()}catch(reason){setError(reason.message)}};if(!session)return <EmptyState title="Acceso restringido" text="Ingresa con una cuenta autorizada para abrir este espacio." action={()=>window.dispatchEvent(new Event('open-auth'))} actionText="Ingresar"/>;if(!authorized)return <ErrorPage code="403"/>;const operational=data.units.filter(unit=>unit.status==='OPERATIONAL').length;return <main className="operations-page page-shell page-top"><div className="operations-heading"><p className="kicker dark"><span/> {provider?'Panel del proveedor':'Panel administrativo'}</p><h1>{provider?'Tus herramientas, bajo tu control.':'Operación con datos verificables.'}</h1><p>{provider?'Publica herramientas y registra sus unidades físicas con autorización validada por el backend.':'Resumen calculado únicamente con respuestas de endpoints administrativos protegidos.'}</p></div>{state==='loading'&&<div className="integration-banner"><Icon name="grid"/><div><strong>Cargando operación</strong><p>Consultando recursos autorizados.</p></div></div>}{state==='error'&&<div className="form-error" role="alert">{error}</div>}{state==='ready'&&<><div className="operations-metrics"><Metric label={provider?'Mis herramientas':'Usuarios'} value={provider?data.tools.length:data.users.length} trend="Dato recibido desde la API"/><Metric label="Unidades operativas" value={operational} trend={`${data.units.length} unidades registradas`}/><Metric label="Categorías" value={data.categories.length} trend="Taxonomía persistida"/></div>{provider?<div className="provider-workspace"><section className="operations-form"><div className="form-tabs"><button className={activeForm==='tool'?'active':''} onClick={()=>setActiveForm('tool')}>Publicar herramienta</button><button className={activeForm==='unit'?'active':''} onClick={()=>setActiveForm('unit')} disabled={!data.tools.length}>Registrar unidad</button></div>{activeForm==='tool'?<form onSubmit={createTool}><h2>Nueva herramienta</h2><label className="form-field"><span>Categoría</span><select name="categoryId" required defaultValue=""><option value="" disabled>Selecciona una categoría</option>{data.categories.map(category=><option key={String(entityId(category.id))} value={String(entityId(category.id))}>{category.name}</option>)}</select></label><label className="form-field"><span>Nombre</span><input name="name" required maxLength="160"/></label><label className="form-field"><span>Descripción</span><textarea name="description" required maxLength="2000"/></label><label className="form-field"><span>Tarifa diaria COP</span><input name="dailyRate" type="number" min="0" step="1" required/></label><label className="check-field"><input name="published" type="checkbox"/><span>Publicar al guardar</span></label><div className="form-hint"><Icon name="shield"/><p>Las fotografías requieren almacenamiento seguro y carga autorizada; este formulario no inventa URLs ni reutiliza el hero como publicación.</p></div><button className="button button-lime" type="submit">Guardar herramienta <Icon name="arrow"/></button></form>:<form onSubmit={createUnit}><h2>Nueva unidad física</h2><label className="form-field"><span>Herramienta</span><select name="toolId" required>{data.tools.map(tool=><option key={String(entityId(tool.id))} value={String(entityId(tool.id))}>{tool.name}</option>)}</select></label><label className="form-field"><span>Código de inventario</span><input name="inventoryCode" required maxLength="120"/></label><label className="form-field"><span>Serial</span><input name="serialNumber" maxLength="160"/></label><label className="form-field"><span>Condición actual</span><select name="currentCondition" defaultValue="GOOD"><option value="GOOD">Buena</option><option value="FAIR">Aceptable</option><option value="NEW">Nueva</option></select></label><button className="button button-lime" type="submit">Registrar unidad <Icon name="arrow"/></button></form>}</section><section className="operations-table"><div className="panel-heading"><div><h2>Mis publicaciones</h2><p>Incluye borradores y herramientas publicadas de este proveedor.</p></div></div>{!data.tools.length?<div className="account-empty"><Icon name="box" size={32}/><h3>Sin herramientas</h3><p>Usa el formulario para crear la primera publicación real.</p></div>:data.tools.map(tool=><article key={String(entityId(tool.id))}><div><span className={`status-pill ${tool.published?'green':'amber'}`}>{tool.published?'Publicada':'Borrador'}</span><h3>{tool.name}</h3><p>{tool.description}</p></div><strong>{money.format(Number(tool.dailyRate?.amount??0))}/día</strong></article>)}</section></div>:<div className="admin-workspace"><section className="operations-table"><div className="panel-heading"><div><h2>Usuarios</h2><p>Datos del endpoint administrativo.</p></div></div>{data.users.map(user=><article key={user.userId}><div><span className={`status-pill ${user.accountStatus==='ACTIVE'?'green':'amber'}`}>{user.accountStatus}</span><h3>{user.displayName}</h3><p>{user.email}</p></div><strong>{new Date(user.registeredAt).toLocaleDateString('es-CO')}</strong></article>)}</section><section className="operations-table"><div className="panel-heading"><div><h2>Categorías</h2><p>{data.categories.length} registros persistidos.</p></div></div>{data.categories.map(category=><article key={String(entityId(category.id))}><div><h3>{category.name}</h3><p>{category.description||'Sin descripción'}</p></div></article>)}</section></div>}</>}</main>}

function ProviderEntryPage({session,onOpenAuth}){const supplier=session?.roles?.includes('SUPPLIER');return <main className="provider-entry"><section className="provider-entry-hero"><div className="page-shell"><p className="kicker"><span/> Para proveedores</p><h1>Haz que tu equipo<br/><em>siga trabajando.</em></h1><p>La publicación requiere una cuenta con rol de proveedor y autorización de servidor. El registro público actual crea únicamente cuentas de cliente.</p><div>{supplier?<button className="button button-lime" onClick={()=>navigate('/panel/proveedor')}>Abrir mi panel <Icon name="arrow"/></button>:<button className="button button-lime" onClick={onOpenAuth}>Ingresar <Icon name="arrow"/></button>}<button className="button button-ghost light" onClick={()=>navigate('/informacion/contacto')}>Consultar activación</button></div></div></section><section className="provider-entry-steps page-shell">{[['01','Identidad y rol','El operador debe asignar el rol de proveedor por un proceso autorizado.'],['02','Publicación','Registra características y precio sin convertir el hero editorial en foto del inventario.'],['03','Unidades','Cada herramienta física conserva serial, estado y disponibilidad.'],['04','Operación','Gestiona solo tus solicitudes, entregas y devoluciones.']].map(([number,title,copy])=><article key={number}><span>{number}</span><h2>{title}</h2><p>{copy}</p></article>)}</section></main>}
function AboutPage(){return <main className="about-page"><section className="about-hero"><img src="/assets/about-bucaramanga-editorial.png" alt="Profesional de construcción observando Bucaramanga al atardecer"/><div className="about-overlay"/><div className="page-shell"><p className="kicker"><span/> Sobre nosotros</p><h1>Somos la plataforma<br/><em>que conecta herramientas</em><br/>con <strong>proyectos reales.</strong></h1><p>Tool Rental nace como una plataforma académica local para conectar capacidad disponible con proyectos del área metropolitana.</p><div><button className="button button-lime" onClick={()=>navigate('/catalogo')}>Explorar catálogo <Icon name="arrow"/></button><button className="button button-ghost light" onClick={()=>navigate('/publicar')}>Conviértete en proveedor</button></div></div></section><section className="about-story page-shell"><article><p className="kicker dark"><span/> Nuestra esencia</p><h2>Más acceso.<br/><em>Más proyectos.</em></h2><p>Diseñamos una experiencia donde el precio base, las fechas, el inventario y cada estado puedan entenderse sin letras pequeñas ni cifras infladas.</p></article><article><p className="kicker dark"><span/> Nuestra misión</p><h2>Una idea local con propósito.</h2><p>Facilitar el acceso responsable a herramientas y dar trazabilidad a proveedores y clientes, conservando la historia completa de cada operación.</p></article></section><section className="values-section page-shell"><p className="kicker dark"><span/> Nuestros valores</p><div>{[['shield','Confianza','Seguridad por capas y estados comprensibles.'],['user','Colaboración','Clientes y proveedores con responsabilidades claras.'],['check','Calidad','Datos reales antes que afirmaciones decorativas.'],['pin','Impacto local','Una cobertura inicial honesta en Santander.']].map(([icon,title,copy])=><article key={title}><Icon name={icon}/><h3>{title}</h3><p>{copy}</p></article>)}</div></section><section className="coverage-section"><div className="page-shell"><div><p className="kicker"><span/> Cobertura local</p><h2>En el corazón<br/>de Santander.</h2><p>La zona operativa inicial está limitada a cuatro municipios del área metropolitana.</p></div><div className="coverage-cards">{serviceLocations.map((city,index)=><article key={city}><span>0{index+1}</span><h3>{city}</h3><p>Santander</p></article>)}</div></div></section></main>}
function HowItWorksPage(){const steps=[['01','Busca','Explora herramientas y consulta su disponibilidad para un periodo inclusivo.'],['02','Solicita','Selecciona recogida o entrega y revisa el cálculo del backend.'],['03','Confirma','El proveedor vuelve a validar unidades antes de confirmar o rechazar.'],['04','Simula el pago','El entorno académico registra el 50 % inicial solo después de la confirmación.'],['05','Recibe y devuelve','La entrega, el alquiler y la devolución conservan estados trazables.']];return <main className="how-page"><section className="how-hero"><div className="page-shell"><p className="kicker"><span/> Cómo funciona</p><h1>Del catálogo a la devolución,<br/><em>sin perder el hilo.</em></h1><p>Un recorrido fiel al comportamiento implementado hoy, sin adelantar capacidades de una pasarela futura.</p><button className="button button-lime" onClick={()=>navigate('/catalogo')}>Explorar catálogo <Icon name="arrow"/></button></div></section><section className="how-timeline page-shell">{steps.map(([number,title,copy])=><article key={number}><span>{number}</span><div><h2>{title}</h2><p>{copy}</p></div></article>)}</section><section className="how-note page-shell"><Icon name="shield"/><div><h2>Pago académico, claramente identificado.</h2><p>Tool Rental no solicita PAN completo ni CVV. La integración con una pasarela sandbox y webhooks firmados sigue pendiente de proveedor y credenciales.</p></div></section></main>}
function InfoPage({type}){const content={privacidad:['Privacidad','Tus datos deben tener un propósito, no una sorpresa.','La política definitiva y el registro persistente de consentimientos continúan pendientes de revisión legal.'],faq:['Preguntas frecuentes','Respuestas para empezar con confianza.','Información basada en el flujo que está implementado actualmente.'],contacto:['Contacto','Un canal real requiere un operador real.','Los datos del operador y los tiempos de atención aún no han sido aprobados; no publicamos teléfonos o correos ficticios.']};const [title,headline,description]=content[type]||content.contacto;const cards=type==='faq'?[['¿Cómo reservo?','Elige una herramienta, define fechas inclusivas y crea una solicitud.'],['¿Cuándo pago?','La simulación académica habilita la primera mitad después de la confirmación del proveedor.'],['¿Existe protección?','El plan opcional aún no tiene valores ni condiciones aprobadas.']]:[['01','Estado actual','Esta página comunica los límites vigentes del proyecto.'],['02','Sin datos inventados','No publicamos canales, responsables o promesas que aún no existen.'],['03','Próximo paso','La decisión legal o comercial debe quedar versionada antes de implementarse.']];return <main className="info-page"><div className="page-shell"><p className="kicker"><span/> {title}</p><h1>{headline}</h1><p>{description}</p><div className="info-grid">{cards.map(item=><article key={item[0]}><span>{item[0]}</span><h2>{item[1]}</h2><p>{item[2]}</p></article>)}</div></div></main>}
function ErrorPage({code='404'}){return <main className="error-page"><span>{code}</span><p className="kicker dark"><i/> Algo no salió como esperábamos</p><h1>{code==='403'?'Este espacio no está disponible para tu rol.':'Parece que esta herramienta cambió de lugar.'}</h1><button className="button button-dark" onClick={()=>navigate('/')}>Volver al inicio <Icon name="arrow"/></button></main>}
function EmptyState({title,text,action,actionText='Limpiar filtros'}){return <main className="empty-state page-shell page-top"><span className="empty-icon"><Icon name="search" size={40}/></span><h1>{title}</h1><p>{text}</p><button className="button button-dark" onClick={action}>{actionText} <Icon name="arrow"/></button></main>}

function App(){
  const [path,setPath]=useState(window.location.pathname)
  const [session,setSession]=useState(readSession())
  const [authOpen,setAuthOpen]=useState(false)
  const [reservation,setReservation]=useState(null)
  const [catalogTools,setCatalogTools]=useState(tools)
  const [dataMode,setDataMode]=useState('demo')
  const [location,setLocation]=useState(defaultLocation)
  const displayedCatalogTools=useMemo(()=>dataMode==='demo'?catalogTools.map(tool=>({...tool,location:`${location}, Santander` })):catalogTools,[catalogTools,dataMode,location])

  const changeLocation=nextLocation=>{
    if(!serviceLocations.includes(nextLocation))return
    setLocation(nextLocation)
    window.localStorage.setItem('tool-rental-location',nextLocation)
    const currentUrl=new URL(window.location.href)
    if(currentUrl.pathname==='/'||currentUrl.pathname==='/catalogo'){
      currentUrl.searchParams.set('municipio',nextLocation)
      window.history.replaceState({},'',`${currentUrl.pathname}?${currentUrl.searchParams}`)
    }
  }

  useEffect(()=>{
    const update=()=>{
      setPath(window.location.pathname)
      const requestedLocation=new URLSearchParams(window.location.search).get('municipio')
      if(serviceLocations.includes(requestedLocation)){
        setLocation(requestedLocation)
        window.localStorage.setItem('tool-rental-location',requestedLocation)
      }
    }
    const open=()=>setAuthOpen(true)
    const updateSession=event=>setSession(event.detail)
    window.addEventListener('popstate',update)
    window.addEventListener('open-auth',open)
    window.addEventListener('tool-rental-session',updateSession)
    api.restoreSession().catch(()=>null)
    api.listCatalog().then(items=>{
      if(items.length){setCatalogTools(items.map(normalizeCatalogTool));setDataMode(import.meta.env.VITE_DEMO_MODE==='true'?'demo':'api')}
    }).catch(()=>setDataMode('demo'))
    return()=>{window.removeEventListener('popstate',update);window.removeEventListener('open-auth',open);window.removeEventListener('tool-rental-session',updateSession)}
  },[])

  useEffect(()=>{
    const elements=[...document.querySelectorAll('[data-reveal]')]
    if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){elements.forEach(element=>element.classList.add('is-visible'));return undefined}
    const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{rootMargin:'0px 0px -8% 0px',threshold:.12})
    elements.forEach(element=>observer.observe(element))
    return()=>observer.disconnect()
  },[path,catalogTools.length])

  const reserve=async selection=>{
    if(selection.tool.source==='api'){
      try{
        const availability=await api.getAvailability(selection.tool.id,selection.startDate,selection.returnDate)
        selection={...selection,equipmentUnitIds:availability.availableEquipmentUnitIds}
      }catch(error){selection={...selection,availabilityError:error.message}}
    }
    setReservation(selection)
    navigate('/cotizacion')
  }
  const login=authenticated=>{
    saveSession(authenticated)
    setSession(authenticated)
    setAuthOpen(false)
  }
  const logout=async()=>{
    await api.logout().catch(()=>null)
    saveSession(null);setSession(null);navigate('/')
  }
  const continueQuote=async logistics=>{
    if(!session){setAuthOpen(true);return}
    if(reservation?.tool.source==='api'&&reservation.equipmentUnitIds?.length&&!session?.demo){
      try{
        const equipmentUnitIds=[reservation.equipmentUnitIds[0]]
        const quote=await api.quoteReservation({startDate:reservation.startDate,returnDate:reservation.returnDate,equipmentUnitIds,fulfillmentMethod:logistics.fulfillmentMethod,deliveryCountryCode:logistics.deliveryCountryCode})
        const created=await api.createReservation({startDate:reservation.startDate,returnDate:reservation.returnDate,equipmentUnitIds,...logistics,scheduledFulfillmentAt:new Date(logistics.scheduledFulfillmentAt).toISOString()})
        setReservation(current=>({...current,quote,reservationId:created.id?.value||created.id}))
      }catch(error){setReservation(current=>({...current,apiError:error.message}));return}
    }
    navigate('/reserva-confirmada')
  }
  const pay=async payment=>{
    if(reservation?.reservationId&&!session?.demo){
      try{
        await api.simulatePayment({reservationId:reservation.reservationId,paymentStage:'FIRST_HALF',idempotencyKey:crypto.randomUUID(),simulationOutcome:'APPROVE',...payment})
      }catch(error){setReservation(current=>({...current,apiError:error.message}));return}
    }
    navigate('/reserva-confirmada')
  }

  let page
  if(path==='/')page=<HomePage catalogTools={displayedCatalogTools} dataMode={dataMode} location={location} onLocationChange={changeLocation}/>
  else if(path==='/catalogo')page=<CatalogPage catalogTools={displayedCatalogTools} dataMode={dataMode} location={location} onLocationChange={changeLocation}/>
  else if(path.startsWith('/herramienta/'))page=<ToolDetailPage id={path.split('/').pop()} onReserve={reserve} catalogTools={displayedCatalogTools} dataMode={dataMode}/>
  else if(path==='/cotizacion')page=<QuotePage reservation={reservation} session={session} onContinue={continueQuote}/>
  else if(path==='/pago')page=<PaymentPage reservation={reservation} onPaid={pay}/>
  else if(path==='/reserva-confirmada')page=<SuccessPage reservation={reservation}/>
  else if(path==='/cuenta')page=<AccountPage session={session} onLogout={logout}/>
  else if(path==='/panel/proveedor')page=<BusinessDashboard role="provider" session={session}/>
  else if(path==='/panel/admin')page=<BusinessDashboard role="admin" session={session}/>
  else if(path==='/publicar')page=<ProviderEntryPage session={session} onOpenAuth={()=>setAuthOpen(true)}/>
  else if(path==='/terms-and-conditions')page=<TermsAndConditionsPage/>
  else if(path==='/nosotros')page=<AboutPage/>
  else if(path==='/como-funciona')page=<HowItWorksPage/>
  else if(path.startsWith('/informacion/'))page=<InfoPage type={path.split('/').pop()}/>
  else if(path==='/403')page=<ErrorPage code="403"/>
  else page=<ErrorPage/>
  const minimal=['/pago','/reserva-confirmada'].includes(path)
  return <div className={`app ${path==='/'?'home-route':''}`}>{!minimal&&<Header path={path} session={session} onOpenAuth={()=>setAuthOpen(true)} location={location} onLocationChange={changeLocation}/>}<div className="page-content page-enter" key={path}>{page}</div>{!minimal&&!path.startsWith('/panel/')&&path!=='/cuenta'&&<Footer/>}{authOpen&&<AuthModal onClose={()=>setAuthOpen(false)} onLogin={login}/>}</div>
}
export default App
